mapper.select:
SELECT COALESCE((
    SELECT COALESCE(SUM(unread_count), 0) FROM crm_whatsapp_conversation
    WHERE tenant_id = #{tenantId} AND user_id = #{userId}
), 0)
+ COALESCE((
    SELECT COALESCE(SUM(unread_count), 0) FROM crm_messenger_conversation
    WHERE tenant_id = #{tenantId} AND user_id = #{userId}
), 0)
+ COALESCE((
    SELECT COALESCE(SUM(unread_count), 0) FROM crm_webchat_conversation
    WHERE tenant_id = #{tenantId} AND user_id = #{userId}
), 0)
+ COALESCE((
    SELECT COALESCE(SUM(unread_count), 0) FROM crm_wechat_mp_conversation
    WHERE user_id = #{userId}
), 0)
